code.python:
class Solution:
    def insertPosition(self, scores: List[int], target: int) -> int:
        lo, hi = 0, len(scores)
        while lo < hi:
            mid = (lo + hi) // 2
            if scores[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo

code.java:
class Solution {
    public int insertPosition(int[] scores, int target) {
        int lo = 0, hi = scores.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (scores[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

